/**
 * Master data: parent departments, departments, designations, leave types
 * and categories.
 *
 * ONE SERVICE FOR FIVE TABLES. Every function takes a `resource` - an entry
 * from MASTER_DATA_RESOURCES in src/enums/master-data.enum.js - and reads the
 * table, the id property and the wording out of it. Five copies of the same
 * forty lines would drift: the third copy forgets `DeletedAt IS NULL` on a
 * list, and nothing fails until a deleted designation turns up in a dropdown.
 *
 * The SQL is still written out, not generated by a query builder: the
 * statements below are the same shape as the ones in organization.service.js
 * and read the same way. What varies between resources is the table name, the
 * id column and one optional join - nothing that changes what the query does.
 *
 * Three rules, the same as everywhere else here:
 *
 *   1. Nothing is ever hard-deleted. Employees point at a department and a
 *      designation with real foreign keys, so "delete" is a DeletedAt stamp
 *      and the endpoint refuses while anything still points at the row.
 *   2. The unique index is the only authority on a duplicate name. A
 *      pre-check SELECT is a second round trip that is still wrong under
 *      concurrency, so the violation is caught and translated instead.
 *   3. Who may call these was settled before the request arrived, by
 *      requireAccess in the route file. Nothing here re-checks a right.
 */
import { query, queryOne } from '../helpers/query.helper.js';
import {
  ParentDepartment,
  Department,
  Designation,
  LeaveType,
  Category,
  Gender,
  MaritalStatus,
  Relationship,
  Skill,
  EmploymentType,
  JobRole,
  EmployeeBand,
  WorkLocationCountry,
  WorkMode,
  BillabilityType,
  ProjectClient,
  CostCenter,
  SourceOfHire,
  OnboardingStatus,
  BackgroundVerificationStatus,
  TaxRegime,
  GovernmentIdType,
  DocumentType,
  DocumentVerificationStatus,
  AssetType,
  AssetModel,
  Qualification,
  Specialization,
  RegularizationType,
  RegularizationRequest,
  EmployeeDetails,
  MASTER_DATA_PUBLIC_PROPS,
} from '../models/index.js';
import { ApiError } from '../utils/api-error.js';
import { MESSAGES, ERROR_CODE, MASTER_DATA } from '../enums/index.js';

/**
 * key -> model. This map is the reason the registry lives in the enums and
 * this does not: an enum that imported src/models would drag the database
 * connection into the enum layer.
 */
const MODELS = Object.freeze({
  [MASTER_DATA.PARENT_DEPARTMENTS]: ParentDepartment,
  [MASTER_DATA.DEPARTMENTS]: Department,
  [MASTER_DATA.DESIGNATIONS]: Designation,
  [MASTER_DATA.LEAVE_TYPES]: LeaveType,
  [MASTER_DATA.CATEGORIES]: Category,
  [MASTER_DATA.GENDERS]: Gender,
  [MASTER_DATA.MARITAL_STATUSES]: MaritalStatus,
  [MASTER_DATA.RELATIONSHIPS]: Relationship,
  [MASTER_DATA.SKILLS]: Skill,
  [MASTER_DATA.EMPLOYMENT_TYPES]: EmploymentType,
  [MASTER_DATA.JOB_ROLES]: JobRole,
  [MASTER_DATA.EMPLOYEE_BANDS]: EmployeeBand,
  [MASTER_DATA.WORK_LOCATION_COUNTRIES]: WorkLocationCountry,
  [MASTER_DATA.WORK_MODES]: WorkMode,
  [MASTER_DATA.BILLABILITY_TYPES]: BillabilityType,
  [MASTER_DATA.PROJECT_CLIENTS]: ProjectClient,
  [MASTER_DATA.COST_CENTERS]: CostCenter,
  [MASTER_DATA.SOURCES_OF_HIRE]: SourceOfHire,
  [MASTER_DATA.ONBOARDING_STATUSES]: OnboardingStatus,
  [MASTER_DATA.BACKGROUND_VERIFICATION_STATUSES]: BackgroundVerificationStatus,
  [MASTER_DATA.TAX_REGIMES]: TaxRegime,
  [MASTER_DATA.GOVERNMENT_ID_TYPES]: GovernmentIdType,
  [MASTER_DATA.DOCUMENT_TYPES]: DocumentType,
  [MASTER_DATA.DOCUMENT_VERIFICATION_STATUSES]: DocumentVerificationStatus,
  [MASTER_DATA.ASSET_TYPES]: AssetType,
  [MASTER_DATA.ASSET_MODELS]: AssetModel,
  [MASTER_DATA.QUALIFICATIONS]: Qualification,
  [MASTER_DATA.SPECIALIZATIONS]: Specialization,

  /* From db/migrations/016, not 009 - but the same three columns and the
     same loop. See the note on its registry entry in master-data.enum.js. */
  [MASTER_DATA.REGULARIZATION_TYPES]: RegularizationType,
});

/**
 * What points at a row, and so what makes deleting it a 409.
 *
 * A leave type and a category have no dependants yet - the leave and
 * help-desk modules do not exist - so they are absent here and their delete
 * has nothing to refuse for.
 */
const DEPENDANTS = Object.freeze({
  [MASTER_DATA.PARENT_DEPARTMENTS]: Object.freeze({
    table: Department.table,
    column: Department.col('parentDepartmentId'),
    code: ERROR_CODE.PARENT_DEPARTMENT_IN_USE,
    countProp: 'departments',
  }),
  [MASTER_DATA.DEPARTMENTS]: Object.freeze({
    table: EmployeeDetails.table,
    column: EmployeeDetails.col('departmentId'),
    code: ERROR_CODE.DEPARTMENT_IN_USE,
    countProp: 'employees',
  }),
  [MASTER_DATA.DESIGNATIONS]: Object.freeze({
    table: EmployeeDetails.table,
    column: EmployeeDetails.col('designationId'),
    code: ERROR_CODE.DESIGNATION_IN_USE,
    countProp: 'employees',
  }),

  /*
    A regularization type that requests have been raised under cannot be
    deleted: tblRegularizationRequest.RegularizationTypeId is a real foreign
    key, and the history would otherwise lose the reason a correction was
    made. Switching it off (IsActive = 0) is the way to retire one.
  */
  [MASTER_DATA.REGULARIZATION_TYPES]: Object.freeze({
    table: RegularizationRequest.table,
    column: RegularizationRequest.col('regularizationTypeId'),
    code: ERROR_CODE.MASTER_DATA_NOT_FOUND,
    countProp: 'requests',
  }),
});

function modelFor(resource) {
  const model = MODELS[resource.key];
  if (!model) {
    // Wiring error, not a request error: a registry entry with no model.
    throw new Error(`No model registered for master-data resource "${resource.key}".`);
  }
  return model;
}

/** Every property a row comes back with, id first. */
function publicProps(resource) {
  return [
    resource.idProp,
    ...(resource.hasParentDepartment ? ['parentDepartmentId'] : []),
    ...MASTER_DATA_PUBLIC_PROPS,
  ];
}

/**
 * The select list, qualified with `m.` on every resource - not only the one
 * that joins. An unqualified Name stops being unambiguous the moment the
 * parent table is in scope, and one code path that is always right beats two
 * that differ in a way nothing tests.
 */
function selectList(resource) {
  const model = modelFor(resource);
  const columns = publicProps(resource).map((prop) => `m.${model.col(prop)} AS ${prop}`);

  if (resource.hasParentDepartment) {
    // The parent's name, for the grid column that would otherwise be an id.
    columns.push(`p.${ParentDepartment.col('name')} AS parentDepartmentName`);
  }

  return columns.join(', ');
}

/** FROM, with the parent join only where there is a parent to join. */
function fromClause(resource) {
  const model = modelFor(resource);

  if (!resource.hasParentDepartment) return `${model.table} AS m`;

  // LEFT JOIN, not INNER: ParentDepartmentId is nullable, and a department
  // whose parent was soft-deleted must still list - with a null parent name,
  // which is exactly what the grid should show.
  return (
    `${model.table} AS m\n` +
    `       LEFT JOIN ${ParentDepartment.table} AS p\n` +
    `              ON p.${ParentDepartment.col('parentDepartmentId')} = ` +
    `m.${model.col('parentDepartmentId')}\n` +
    `             AND p.${ParentDepartment.col('deletedAt')} IS NULL`
  );
}

/**
 * BIGINT arrives from the driver as a STRING - it has no way to know the
 * value fits, so it never narrows. The same conversion organization.service.js
 * does, and for the same reason: `data.departmentId === 1` silently being
 * false is a worse bug than a ceiling no lookup table will reach.
 */
function withNumericIds(resource, row) {
  if (!row) return row;

  const copy = { ...row };
  for (const prop of [resource.idProp, 'parentDepartmentId']) {
    if (copy[prop] !== undefined && copy[prop] !== null) copy[prop] = Number(copy[prop]);
  }
  return copy;
}

/** 2627 is a UNIQUE/PK constraint, 2601 a unique index. Both mean "taken". */
function uniqueViolation(error) {
  return error?.number === 2601 || error?.number === 2627;
}

/** Turns a unique-index violation on Name into this resource's 409. */
function conflictFor(resource, error) {
  if (!uniqueViolation(error)) return error;

  return ApiError.conflict(resource.messages.nameExists, {
    code: ERROR_CODE.NAME_ALREADY_EXISTS,
  });
}

/**
 * Checks the chosen parent before the insert, so a bad id is a 400 naming the
 * parent rather than a foreign-key 547 the client cannot read.
 *
 * Inactive parents are allowed on purpose: switching a parent off should stop
 * it being offered to new departments, which is the UI's job, not break the
 * save of a department that already sits under it.
 */
async function assertParentExists(parentDepartmentId) {
  const row = await queryOne(
    `SELECT TOP (1) ${ParentDepartment.col('parentDepartmentId')} AS parentDepartmentId
       FROM ${ParentDepartment.table}
      WHERE ${ParentDepartment.col('parentDepartmentId')} = @parentDepartmentId
        AND ${ParentDepartment.col('deletedAt')} IS NULL`,
    ParentDepartment.params({ parentDepartmentId }),
  );

  if (!row) {
    throw ApiError.badRequest(MESSAGES.PARENT_DEPARTMENT_NOT_FOUND, {
      code: ERROR_CODE.MASTER_DATA_NOT_FOUND,
    });
  }
}

/* -------------------------------------------------------------------------- */
/* Read                                                                       */
/* -------------------------------------------------------------------------- */

/**
 * One list, newest-last by name.
 *
 * @param {object} resource from MASTER_DATA_RESOURCES
 * @param {object} [filters]
 * @param {boolean} [filters.isActive]            a dropdown asks for the live ones
 * @param {string}  [filters.search]              matches anywhere in the name
 * @param {number}  [filters.parentDepartmentId]  departments only
 */
export async function listMasterData(resource, filters = {}) {
  const model = modelFor(resource);

  const where = [`m.${model.col('deletedAt')} IS NULL`];
  const bound = {};

  if (filters.isActive !== undefined) {
    where.push(`m.${model.col('isActive')} = @isActive`);
    bound.isActive = model.param('isActive', filters.isActive);
  }

  if (filters.search) {
    // Parameterised, so the LIKE wildcards in a search term are data. The
    // leading % costs the index - acceptable on a list of this size, and
    // "find me every QA designation" is what the box is for.
    where.push(`m.${model.col('name')} LIKE @search`);
    bound.search = model.param('name', `%${filters.search}%`);
  }

  if (resource.hasParentDepartment && filters.parentDepartmentId !== undefined) {
    where.push(`m.${model.col('parentDepartmentId')} = @parentDepartmentId`);
    bound.parentDepartmentId = model.param('parentDepartmentId', filters.parentDepartmentId);
  }

  const rows = await query(
    `SELECT ${selectList(resource)}
       FROM ${fromClause(resource)}
      WHERE ${where.join('\n        AND ')}
      ORDER BY m.${model.col('name')}`,
    bound,
  );

  return rows.map((row) => withNumericIds(resource, row));
}

/** One row, or a 404 in this resource's own words. */
export async function getMasterData(resource, id) {
  const model = modelFor(resource);

  const row = await queryOne(
    `SELECT ${selectList(resource)}
       FROM ${fromClause(resource)}
      WHERE m.${model.col(resource.idProp)} = @id
        AND m.${model.col('deletedAt')} IS NULL`,
    { id: model.param(resource.idProp, id) },
  );

  if (!row) {
    throw ApiError.notFound(resource.messages.notFound, {
      code: ERROR_CODE.MASTER_DATA_NOT_FOUND,
    });
  }

  return withNumericIds(resource, row);
}

/* -------------------------------------------------------------------------- */
/* Write                                                                      */
/* -------------------------------------------------------------------------- */

/**
 * @param {object} resource from MASTER_DATA_RESOURCES
 * @param {number} actorId  EmployeeDetailId of the caller
 * @param {object} input    already validated and cleaned by the controller
 */
export async function createMasterData(resource, actorId, input) {
  const model = modelFor(resource);

  if (resource.hasParentDepartment && input.parentDepartmentId != null) {
    await assertParentExists(input.parentDepartmentId);
  }

  const columns = [model.col('name'), model.col('description')];
  const values = ['@name', '@description'];
  const params = {
    ...model.params({
      name: input.name,
      description: input.description ?? null,
    }),
    actorId: model.param('createdBy', actorId),
  };

  if (resource.hasParentDepartment) {
    columns.push(model.col('parentDepartmentId'));
    values.push('@parentDepartmentId');
    params.parentDepartmentId = model.param(
      'parentDepartmentId',
      input.parentDepartmentId ?? null,
    );
  }

  // IsActive is left to its DEFAULT of 1: a list a client just created and
  // cannot see would be a strange thing to allow, and switching it off is
  // what the edit screen is for.
  columns.push(model.col('createdBy'), model.col('modifiedBy'));
  values.push('@actorId', '@actorId');

  let created;

  try {
    created = await queryOne(
      `INSERT INTO ${model.table} (${columns.join(', ')})
       OUTPUT inserted.${model.col(resource.idProp)} AS id
       VALUES (${values.join(', ')})`,
      params,
    );
  } catch (error) {
    throw conflictFor(resource, error);
  }

  // Re-read rather than OUTPUT the whole row: OUTPUT cannot see the joined
  // parent name, and a create that answered with a different shape from a
  // read is how a client ends up with two code paths for one record.
  return getMasterData(resource, created.id);
}

/**
 * Full replace, PUT semantics: a field the client leaves out becomes NULL.
 *
 * The same decision as updateOrganization - the master-data screens post the
 * whole form back, and a PATCH that silently keeps an old value is how a
 * cleared description reappears after a reload.
 */
export async function updateMasterData(resource, actorId, id, input) {
  const model = modelFor(resource);

  if (resource.hasParentDepartment && input.parentDepartmentId != null) {
    await assertParentExists(input.parentDepartmentId);
  }

  const assignments = [
    `${model.col('name')} = @name`,
    `${model.col('description')} = @description`,
    `${model.col('isActive')} = @isActive`,
  ];
  const params = {
    ...model.params({
      name: input.name,
      description: input.description ?? null,
      isActive: input.isActive ?? true,
    }),
    id: model.param(resource.idProp, id),
    actorId: model.param('modifiedBy', actorId),
  };

  if (resource.hasParentDepartment) {
    assignments.push(`${model.col('parentDepartmentId')} = @parentDepartmentId`);
    params.parentDepartmentId = model.param(
      'parentDepartmentId',
      input.parentDepartmentId ?? null,
    );
  }

  assignments.push(
    `${model.col('modifiedBy')} = @actorId`,
    `${model.col('modifiedAt')} = SYSUTCDATETIME()`,
  );

  let updated;

  try {
    updated = await queryOne(
      `UPDATE ${model.table}
          SET ${assignments.join(',\n              ')}
        OUTPUT inserted.${model.col(resource.idProp)} AS id
        WHERE ${model.col(resource.idProp)} = @id
          AND ${model.col('deletedAt')} IS NULL`,
      params,
    );
  } catch (error) {
    throw conflictFor(resource, error);
  }

  // OUTPUT returns nothing when the WHERE matched nothing, which is the only
  // way to tell "updated" from "no such row" without a second SELECT.
  if (!updated) {
    throw ApiError.notFound(resource.messages.notFound, {
      code: ERROR_CODE.MASTER_DATA_NOT_FOUND,
    });
  }

  return getMasterData(resource, updated.id);
}

/**
 * Soft-deletes a row, unless something still points at it.
 *
 * The dependant check is not belt-and-braces over the foreign key: the key
 * cannot help here, because this is an UPDATE and the references stay valid.
 * Without it, deleting a department would leave employees pointing at a row
 * no screen lists, and nothing would complain until somebody asked why the
 * department filter was empty.
 */
export async function deleteMasterData(resource, actorId, id) {
  const model = modelFor(resource);
  const dependant = DEPENDANTS[resource.key];

  if (dependant) {
    const inUse = await queryOne(
      `SELECT COUNT(*) AS usedBy
         FROM ${dependant.table}
        WHERE ${dependant.column} = @id
          AND DeletedAt IS NULL`,
      { id: model.param(resource.idProp, id) },
    );

    if (inUse && inUse.usedBy > 0) {
      throw ApiError.conflict(resource.messages.inUse, {
        code: dependant.code,
        [dependant.countProp]: inUse.usedBy,
      });
    }
  }

  const row = await queryOne(
    `UPDATE ${model.table}
        SET ${model.col('deletedAt')} = SYSUTCDATETIME(),
            ${model.col('modifiedBy')} = @actorId,
            ${model.col('modifiedAt')} = SYSUTCDATETIME()
      OUTPUT deleted.${model.col(resource.idProp)} AS ${resource.idProp},
             deleted.${model.col('name')} AS name
      WHERE ${model.col(resource.idProp)} = @id
        AND ${model.col('deletedAt')} IS NULL`,
    {
      id: model.param(resource.idProp, id),
      actorId: model.param('modifiedBy', actorId),
    },
  );

  if (!row) {
    throw ApiError.notFound(resource.messages.notFound, {
      code: ERROR_CODE.MASTER_DATA_NOT_FOUND,
    });
  }

  return withNumericIds(resource, row);
}
